        "f82185e9de674056baf341ae59029d45": {
          "id": "f82185e9de674056baf341ae59029d45",
          "name": "User Lookup",
          "script": "(function execute() {\n   \n        var identityGr = new GlideRecordSecure(\"x_aleen_snguardian_identity\");\n        identityGr.addQuery('email', vaInputs.user_email);\n        identityGr.addQuery('is_deleted', false);\n        identityGr.query();\n        if (identityGr.next()) {\n            var user_type = identityGr.type.code;\n            vaVars.guardian_user_sys_id = identityGr.sys_id.toString();\n            vaVars.user_name = identityGr.full_name.toString();\n            vaVars.user_photo = identityGr.photo.toString();\n            vaVars.user_type = identityGr.type.name.toString();\n            vaVars.user_type_sys_id = identityGr.type.toString();\n            if (user_type == 'VISITOR') {\n                var visitorGr = new GlideRecordSecure(\"x_aleen_snguardian_visitor\");\n                if (visitorGr.get(identityGr.sys_id)) {\n                   vaVars.user_status = visitorGr.visitor_status.name.toString();\n                   vaVars.user_number = visitorGr.number.toString();\n                }\n            } else {\n                vaVars.user_status = identityGr.status.name.toString();\n                vaVars.user_number = identityGr.number.toString();\n            }\n        } else {\n            vaVars.guardian_user_sys_id = '';\n            vaVars.user_name = '';\n            vaVars.user_photo = '';\n            vaVars.user_type = '';\n            vaVars.user_status = '';\n            vaVars.user_number = '';\n            vaVars.user_type_sys_id ='';\n        }\n     \n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        }
